mapper.update:
update dict_data
update_user = #{updateUser}, update_time = #{updateTime}, dict_type_id = #{dictTypeId}, label = #{label}, value = #{value}, is_default = #{isDefault}, status = #{status}, sort = #{sort}, remark = #{remark}
where id = #{id}

mapper.select:
select d.id, d.dict_type_id, d.label, d.value, d.is_default, d.status, d.sort, d.remark, d.create_time, d.update_time, d.create_user, d.update_user from dict_data d left join dict_type t on d.dict_type_id = t.id
and t.code = #{dictTypeCode}
and d.label like concat('%', #{label}, '%')
and d.status = #{status}
order by d.sort desc
